): AsyncGenerator<StreamResponse> {
  const provider = globalRegistry.getProviderForAgent(agentId);

// Each continuation receives exactly the result of the previous delegation.
let currentRequest = providerRequest;
while (true) {
let continuation: string | undefined;
try {
for await (const response of provider.executeChat(currentRequest, {

if (response.type === "tool_use" && response.toolName === "delegate_task") {
  const input = response.toolInput as { agent_id?: string; instructions?: string } | undefined;
  const target = input?.agent_id || "";
  const toolUseId = response.toolUseId || crypto.randomUUID();
  yield { type: "claude_json", data: { type: "assistant", message: { content: [{ type: "tool_use", id: toolUseId, name: response.toolName, input: response.toolInput }] } } };
  const childResult: { text: string; error?: string } = { text: "" };
  if (ancestors.includes(target) || target === agentId) {
    childResult.error = `Circular delegation detected for agent '${target}'`;
    yield { type: "error", error: childResult.error };
  } else if (!globalRegistry.getAgent(target) || !globalRegistry.getProviderForAgent(target)) {
    childResult.error = `Agent '${target}' not found or provider not available`;
    yield { type: "error", error: childResult.error };
  } else if (typeof input?.instructions !== "string") {
    childResult.error = "Delegation instructions are required";
  } else {
    yield* executeSingleAgent(target, { ...request, message: input.instructions, sessionId: undefined, workingDirectory: undefined }, null, abortController, debugMode, [...ancestors, agentId], childResult);
  }
  continuation = JSON.stringify({ type: "tool_result", is_error: !!childResult.error, content: childResult.error || childResult.text || "Agent returned no text.", tool_use_id: toolUseId });
  break;
}
if (response.type === "text" && result) result.text += response.content || "";
// Convert provider response to stream response
const chatRoomMessage = createChatRoomMessage(response, agentId);

    } else if (response.type === "done") {
      yield { type: "done" };
      return;
    } else if (response.type === "error") {
      yield { type: "error", error: response.error };
      return;
    }
  }
}

    } else if (response.type === "done") {
      if (!result) yield { type: "done" };
      return;
    } else if (response.type === "error") {
      if (result) result.error = response.error || "Agent execution failed";
      else yield { type: "error", error: response.error };
      return;
    }
  }
  } catch (error) {
    if (!result) throw error;
    result.error = error instanceof Error ? error.message : String(error);
    return;
  }
  if (continuation === undefined) return;
  currentRequest = { ...providerRequest, message: continuation };
  }
